			i++;
		}
		else if(s[i]=='d'&&s[i+1]=='o'&&s[i+2]=='t'&&(i!=n-3))
		{
			cout<<'.';
			done[i+1]=true;
			done[i+2]=true;
			i+=2;
		}
		else cout<<s[i];
	}
	forn(i,n)if(!done[i])cout<<s[i];
